void FMKIRoadLegacyRedirects::Register()
{
	TArray<FCoreRedirect> Redirects;
	Redirects.Reserve(UE_ARRAY_COUNT(GLegacyRedirects));
	for (const FMKIRoadLegacyRedirect& Redirect : GLegacyRedirects) Redirects.Emplace(Redirect.Type, Redirect.OldName, Redirect.NewName);
	FCoreRedirects::AddRedirectList(Redirects, TEXT("MKIRoads legacy names"));
}
